package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen0Test {

    @Test
    public void testTranslate_MatchLongestFirst() throws IOException {
        // Setup: "abc" -> "1", "ab" -> "2"
        // Greedy algorithm should pick "abc"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"abc", "1"},
                new CharSequence[]{"ab", "2"}
        );
        StringWriter out = new StringWriter();
        String input = "abc";

        int length = translator.translate(input, 0, out);

        assertEquals(3, length);
        assertEquals("1", out.toString());
    }










}

